@media(max-width:1050px){.map-canvas{grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto clamp(480px,65dvh,700px) auto auto;grid-template-areas:"topbar" "filters" "map" "player" "inspector"}.map-topbar{gap:10px}.map-actions{margin-left:0}.risk-inspector{max-height:550px;display:grid;grid-template-columns:1fr 1fr}.selection-panel{max-height:none}.map-range{margin:12px 0 0;display:flex}.is-focused{grid-template-rows:auto auto clamp(520px,75dvh,800px) auto}.is-focused .risk-inspector{display:none}.timeline-panel>span{display:none}}
@media(max-width:600px){.map-topbar h2{font-size:22px}.map-topbar{gap:8px}.map-actions{width:100%;gap:0}.map-actions button{font-size:11px;padding:6px 8px}.map-canvas{gap:10px;grid-template-rows:auto auto clamp(400px,52dvh,460px) auto auto}.risk-inspector{display:flex;max-height:650px}.selection-panel{max-height:340px}.map-heading{padding:12px}.map-heading h2{font-size:17px}.timeline-panel{padding:12px;gap:8px}.legend-panel{right:8px;top:100px;max-width:calc(100% - 16px)}.is-focused{grid-template-rows:auto auto clamp(520px,75dvh,800px) auto}}

